CREATE TABLE p2p_bewertung (inhalt_sha TEXT NOT NULL, pub TEXT NOT NULL, netz TEXT NOT NULL, seq INTEGER NOT NULL, gezeigt REAL NOT NULL,
                                                     ja REAL NOT NULL, nein REAL NOT NULL, bestaetigt REAL NOT NULL, widerlegt REAL NOT NULL, zeit TEXT NOT NULL,
                                                     PRIMARY KEY (inhalt_sha, pub));
CREATE TABLE p2p_gesehen (sha TEXT PRIMARY KEY, oid TEXT NOT NULL, herausgeber TEXT NOT NULL, anzahl INTEGER NOT NULL DEFAULT 1);
