CREATE TABLE seite_eigen (rev TEXT PRIMARY KEY, netz TEXT NOT NULL, instanz TEXT NOT NULL, schluessel TEXT NOT NULL);
CREATE TABLE seite_rev (netz TEXT NOT NULL, rev TEXT NOT NULL, seite TEXT NOT NULL, eltern TEXT NOT NULL, pub TEXT, instanz TEXT,
                                                 seq INTEGER, status TEXT NOT NULL, daten TEXT, netz_id TEXT NOT NULL, loesch_hash TEXT NOT NULL,
