CREATE TABLE vektor (id TEXT PRIMARY KEY, dim INTEGER NOT NULL, modell TEXT NOT NULL, zeit TEXT NOT NULL, roh BLOB NOT NULL, verglichen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE vi_index (name TEXT PRIMARY KEY, art TEXT NOT NULL DEFAULT 'projekt', beschreibung TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '[]', erstellt TEXT NOT NULL, quelle TEXT NOT NULL DEFAULT 'automatisch');
CREATE TABLE vil_gewicht (wort TEXT NOT NULL, frageart TEXT NOT NULL, ja REAL NOT NULL, nein REAL NOT NULL, n REAL NOT NULL, hash TEXT NOT NULL, zeit TEXT NOT NULL, PRIMARY KEY (wort, frageart));
CREATE TABLE vil_gewicht_netz (hash TEXT NOT NULL, pub TEXT NOT NULL, netz TEXT NOT NULL, seq INTEGER NOT NULL, ja REAL NOT NULL, nein REAL NOT NULL, zeit TEXT NOT NULL, PRIMARY KEY (hash, pub));
